def fetch_all_orders(query, page_limit=20):
    orders=[]
    page_index=0
    while True:
        page_orders = apis.amazon.show_orders(access_token=amazon_token, query=query, page_index=page_index, page_limit=page_limit, sort_by='-created_at')
        # show_orders likely returns list directly
        if isinstance(page_orders, dict):
            page_list = page_orders.get('success', [])
        else:
            page_list = page_orders
        print('page', page_index, 'count', len(page_list))
        if not page_list:
            break
        orders.extend(page_list)
        page_index += 1
        if page_index>50:
            break
    return orders

orders = fetch_all_orders('Hanes tagless crewneck undershirts')
print('total orders fetched', len(orders))
for o in orders[:10]:
    print('order', o['order_id'], 'created_at', o['created_at'], 'items', len(o.get('order_items',[])))

# Extract Hanes Tagless Crewneck Undershirt items in this week's orders that are NOT extra-large
from datetime import datetime, timedelta

now = datetime.now()
start_of_week = now - timedelta(days=now.weekday())
end_of_week = start_of_week + timedelta(days=7)

# Ensure we have week_orders; if not, refetch
if 'orders' not in globals():
    def fetch_all_orders(query, page_limit=20):
        orders=[]
        page_index=0
        while True:
            page_orders = apis.amazon.show_orders(access_token=amazon_token, query=query, page_index=page_index, page_limit=page_limit, sort_by='-created_at')
            page_list = page_orders.get('success', []) if isinstance(page_orders, dict) else page_orders
            if not page_list:
                break
            orders.extend(page_list)
            page_index += 1
            if page_index>50:
                break
        return orders
    orders = fetch_all_orders('Hanes tagless crewneck undershirts')

# build week_orders if missing
if 'week_orders' not in globals():
    def iso_to_dt(s):
        if s.endswith('Z'):
            s = s[:-1]
        return datetime.fromisoformat(s)
    week_orders=[]
    for o in orders:
        created_at = iso_to_dt(o['created_at'])
        if start_of_week <= created_at < end_of_week:
            week_orders.append(o)

# collect Hanes undershirt items
hanes_items=[]
for o in week_orders:
    for it in o.get('order_items', []):
        if it.get('product_name','').startswith('Hanes Men's Tagless Crewneck Undershirt'):
            hanes_items.append({
                'order_id': o['order_id'],
                'product_id': it['product_id'],
                'product_name': it.get('product_name'),
                'ordered_quantity': it.get('ordered_quantity'),
                'returned_quantity': it.get('returned_quantity'),
            })

print('week_orders_count', len(week_orders))
print('hanes_items_count', len(hanes_items))
print(hanes_items)

# Determine which are extra-large by showing product for each product_id
# We'll map product_id -> relative_size
sizes={}
for item in hanes_items:
    pid=item['product_id']
    if pid not in sizes:
        p=apis.amazon.show_product(product_id=pid)
        sizes[pid]=p.get('relative_size')

print('sizes map', sizes)

# filter to not extra-large and not already returned
eligible=[]
for item in hanes_items:
    pid=item['product_id']
    rel=sizes.get(pid)
    if rel!='extra-large' and item.get('returned_quantity',0)==0:
        eligible.append(item)

print('eligible_for_return_count', len(eligible))
print(eligible)

# Show what candidate lists are currently in globals
candidates = {}
for name in ['eligible','hanes_items','week_orders','orders']:
    if name in globals():
        try:
            candidates[name] = len(globals()[name])
        except Exception:
            candidates[name] = str(type(globals()[name]))
print('candidate_lengths', candidates)
if 'eligible' in globals():
    print('eligible', globals()['eligible'])

